// ══ CONFIGURE AQUI (só estes valores) ═════════════════════════════════
const CONFIG = {
  segredo: 'TROQUE-POR-UMA-SENHA-LONGA',            // o mesmo valor do cabeçalho x-nexla-segredo nos webhooks do Supabase
  supabaseUrl: 'https://lyvknbggtimdivywfeys.supabase.co',
  site: 'https://www.nexla.com.br/academy',
  evolutionUrl: 'https://SUA-EVOLUTION-API.com',     // endereço da Evolution API, sem barra no final
  evolutionInstancia: 'NOME-DA-INSTANCIA',
  evolutionApiKey: 'SUA-APIKEY-DA-EVOLUTION',
  esperaPixHoras: 1,        // lembrete se o Pix não for pago em 1 hora
  esperaBoletoHoras: 24,    // lembrete se o boleto não for pago em 24 horas
};
// ═══════════════════════════════════════════════════════════════════════

// Recebe o aviso do Supabase (Database Webhook) e decide qual mensagem mandar.
// Avisos que não interessam (ou sem o segredo certo) param aqui: o fluxo não segue.
const saida = [];
for (const item of $input.all()) {
  const h = item.json.headers || {};
  const b = item.json.body || {};
  if ((h['x-nexla-segredo'] || '') !== CONFIG.segredo) continue;   // não veio do nosso Supabase

  const r = b.record || {};
  const o = b.old_record || {};
  let evento = null;

  // Conta criada (só alunos; o admin não recebe)
  if (b.table === 'academy_profiles' && b.type === 'INSERT' && (r.role || 'aluno') === 'aluno') evento = 'boas_vindas';

  // Certificado emitido (o aluno chegou a 90% e abriu o certificado)
  if (b.table === 'academy_certificates' && b.type === 'INSERT') evento = 'certificado';

  // Pedido mudou: só age quando o status muda (o Mercado Pago avisa várias vezes o mesmo pagamento)
  if (b.table === 'academy_orders' && b.type === 'UPDATE') {
    const mudou = r.status !== o.status;
    const forma = r.forma_pagamento || '';
    if (r.status === 'pago' && mudou) evento = Number(r.total) > 0 ? 'pago' : 'liberado_gratis';
    else if (r.status === 'pendente' && forma && !o.forma_pagamento) {
      // Gerou o Pix/boleto agora (antes disso o pedido só existia porque abriu a tela de pagamento)
      evento = (forma === 'bank_transfer' || forma === 'pix') ? 'pix_pendente' : forma === 'ticket' ? 'boleto_pendente' : 'em_analise';
    }
    else if (r.status === 'recusado' && mudou) evento = 'recusado';
    else if (r.status === 'cancelado' && mudou && forma) evento = 'cancelado';   // sem forma = abandonou antes de pagar: não avisa
    else if (r.status === 'reembolsado' && mudou) evento = 'reembolsado';
  }

  if (!evento) continue;
  saida.push({ json: {
    ...CONFIG,
    evento,
    userId: b.table === 'academy_profiles' ? r.id : r.user_id,
    courseId: r.course_id || null,
    pedidoId: b.table === 'academy_orders' ? r.id : null,
    total: Number(r.total || 0),
    codigo: r.codigo || null,
    cursoNome: r.curso || null,
  } });
}
return saida;

// Monta o texto do WhatsApp e o e-mail de cada situação
const c = $('Classificar evento').first().json;
const a = $('Buscar aluno').first().json || {};
const cu = $('Buscar curso').first().json || {};

const nome = String(a.nome || '').trim();
const n = nome.split(/\s+/)[0] || '';
const ola = `Olá${n ? `, ${n}` : ''}!`;
const curso = cu.titulo || c.cursoNome || 'seu curso';
const slug = cu.slug || '';
const site = c.site;
const valor = 'R$ ' + Number(c.total || 0).toFixed(2).replace('.', ',');
const esc = s => String(s).replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const L = {
  painel: `${site}/painel`,
  curso: slug ? `${site}/curso/${slug}` : `${site}/painel`,
  comprar: slug ? `${site}/comprar/${slug}` : `${site}/cursos`,
  certificados: `${site}/certificados`,
  validar: `${site}/validar/${c.codigo || ''}`,
};
const C = `<strong>${esc(curso)}</strong>`;

const MSG = {
  boas_vindas: {
    assunto: 'Bem-vindo(a) à Nexla Academy',
    titulo: `${ola} Sua conta está pronta.`,
    paragrafos: ['Na Nexla Academy você assiste às aulas de amostra grátis, conhece todos os cursos e acompanha o seu progresso.', 'Qualquer dúvida, é só responder este e-mail ou chamar no WhatsApp.'],
    botao: ['Acessar a Nexla Academy', L.painel],
    whatsapp: `${ola} Que bom ter você na *Nexla Academy*.\n\nSua conta está pronta. Por lá você assiste às aulas de amostra grátis e conhece todos os cursos:\n${L.painel}\n\nQualquer dúvida, é só responder aqui.`,
  },
  pix_pendente: {
    assunto: `Seu Pix do curso ${curso} foi gerado`,
    titulo: 'Seu Pix foi gerado',
    paragrafos: [`O Pix de ${valor} do curso ${C} está aguardando pagamento.`, 'Assim que o pagamento cair, o acesso é liberado na hora e você recebe uma confirmação.', 'Se o código expirou, é só gerar um novo pelo botão abaixo.'],
    botao: ['Gerar um novo Pix', L.comprar],
    whatsapp: `${ola} O Pix de ${valor} do curso *${curso}* foi gerado e está aguardando pagamento.\n\nAssim que cair, o acesso é liberado na hora e eu te aviso aqui.\n\nSe o código expirou, gere outro em:\n${L.comprar}`,
    lembrete: {
      assunto: `Seu Pix do curso ${curso} ainda está pendente`,
      titulo: 'Seu Pix ainda não foi pago',
      paragrafos: [`O Pix de ${valor} do curso ${C} ainda está aguardando pagamento.`, 'Se quiser garantir seu acesso, pague o código que você gerou ou gere um novo pelo botão abaixo.'],
      botao: ['Concluir a compra', L.comprar],
      whatsapp: `${ola} Passando para lembrar: o Pix do curso *${curso}* ainda está aguardando pagamento.\n\nSe quiser garantir seu acesso, é só pagar o código que você gerou ou gerar um novo aqui:\n${L.comprar}\n\nFicou alguma dúvida? É só responder.`,
    },
  },
  boleto_pendente: {
    assunto: `Seu boleto do curso ${curso} foi gerado`,
    titulo: 'Seu boleto foi gerado',
    paragrafos: [`O boleto de ${valor} do curso ${C} está aguardando pagamento.`, 'Depois de pago, o banco leva até 3 dias úteis para confirmar. O acesso é liberado sozinho e você recebe uma confirmação.'],
    botao: ['Ver meus cursos', L.painel],
    whatsapp: `${ola} O boleto de ${valor} do curso *${curso}* foi gerado.\n\nDepois de pago, o banco leva até 3 dias úteis para confirmar. O acesso é liberado sozinho e eu te aviso aqui.\n\nPrefere liberar na hora? Pague com Pix:\n${L.comprar}`,
    lembrete: {
      assunto: `Seu boleto do curso ${curso} ainda não foi pago`,
      titulo: 'Seu boleto ainda não foi pago',
      paragrafos: [`O boleto de ${valor} do curso ${C} ainda não foi pago.`, 'Se preferir liberar o acesso na hora, você pode pagar com Pix pelo botão abaixo.'],
      botao: ['Pagar com Pix', L.comprar],
      whatsapp: `${ola} O boleto do curso *${curso}* ainda não foi pago.\n\nSe preferir liberar o acesso na hora, pague com Pix:\n${L.comprar}`,
    },
  },
  em_analise: {
    assunto: `Pagamento do curso ${curso} em análise`,
    titulo: 'Seu pagamento está em análise',
    paragrafos: [`O Mercado Pago está analisando o pagamento do curso ${C}. Isso costuma levar poucos minutos.`, 'Assim que for aprovado, o acesso é liberado sozinho e você recebe uma confirmação.'],
    botao: ['Ver meus cursos', L.painel],
    whatsapp: `${ola} O pagamento do curso *${curso}* está em análise no Mercado Pago. Costuma levar poucos minutos.\n\nAssim que for aprovado, o acesso é liberado sozinho e eu te aviso aqui.`,
  },
  pago: {
    assunto: `Pagamento confirmado: ${curso}`,
    titulo: 'Pagamento confirmado!',
    paragrafos: [`Seu pagamento de ${valor} foi aprovado e o curso ${C} já está liberado na sua conta.`, 'Você tem 7 dias de garantia: se não gostar, devolvemos o valor.'],
    botao: ['Começar o curso', L.curso],
    whatsapp: `${ola} Pagamento confirmado!\n\nO curso *${curso}* já está liberado na sua conta. Comece agora:\n${L.curso}\n\nBons estudos!`,
  },
  liberado_gratis: {
    assunto: `Curso liberado: ${curso}`,
    titulo: 'Seu curso foi liberado!',
    paragrafos: [`O curso ${C} já está na sua conta, sem custo.`],
    botao: ['Começar o curso', L.curso],
    whatsapp: `${ola} O curso *${curso}* foi liberado na sua conta. Comece agora:\n${L.curso}`,
  },
  recusado: {
    assunto: `Pagamento não aprovado: ${curso}`,
    titulo: 'Seu pagamento não foi aprovado',
    paragrafos: [`O pagamento do curso ${C} foi recusado pelo Mercado Pago. Nenhum valor foi cobrado.`, 'Você pode tentar de novo com outro cartão ou pagar com Pix, que libera na hora.'],
    botao: ['Tentar de novo', L.comprar],
    whatsapp: `${ola} O pagamento do curso *${curso}* não foi aprovado e nenhum valor foi cobrado.\n\nVocê pode tentar de novo com outro cartão ou pagar com Pix, que libera na hora:\n${L.comprar}`,
  },
  cancelado: {
    assunto: `Pagamento cancelado: ${curso}`,
    titulo: 'Seu pagamento foi cancelado',
    paragrafos: [`O pagamento do curso ${C} foi cancelado (o Pix ou o boleto pode ter expirado). Nenhum valor foi cobrado.`, 'Se ainda quiser o curso, é só gerar um novo pagamento.'],
    botao: ['Gerar novo pagamento', L.comprar],
    whatsapp: `${ola} O pagamento do curso *${curso}* foi cancelado (o Pix ou o boleto pode ter expirado). Nenhum valor foi cobrado.\n\nSe ainda quiser o curso, gere um novo pagamento:\n${L.comprar}`,
  },
  reembolsado: {
    assunto: `Reembolso processado: ${curso}`,
    titulo: 'Seu reembolso foi processado',
    paragrafos: [`O reembolso de ${valor} do curso ${C} foi processado e o valor volta pelo mesmo meio de pagamento. No cartão, aparece na fatura conforme o prazo da operadora.`, 'Se puder, conte o que podemos melhorar: é só responder este e-mail.'],
    botao: null,
    whatsapp: `${ola} O reembolso do curso *${curso}* foi processado e o valor volta pelo mesmo meio de pagamento.\n\nSe puder, conte o que podemos melhorar. Sua opinião ajuda muito.`,
  },
  certificado: {
    assunto: `Seu certificado do curso ${curso} está disponível`,
    titulo: `Parabéns${n ? `, ${esc(n)}` : ''}! Seu certificado está pronto.`,
    paragrafos: [`Você concluiu o curso ${C} e o seu certificado já pode ser baixado em PDF.`, `Código de validação: <strong>${esc(c.codigo || '')}</strong>. Qualquer pessoa pode conferir em <a href="${L.validar}">${esc(L.validar)}</a>.`],
    botao: ['Baixar meu certificado', L.certificados],
    whatsapp: `Parabéns${n ? `, ${n}` : ''}! Você concluiu o curso *${curso}* e o seu certificado já está disponível:\n${L.certificados}\n\nCódigo de validação: *${c.codigo || ''}*\nQualquer pessoa confere em ${L.validar}`,
  },
};

const html = m => `<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;padding:28px 24px;color:#0F172A">
<p style="font-size:17px;font-weight:bold;color:#4F46E5;margin:0 0 20px">Nexla Academy</p>
<h1 style="font-size:22px;line-height:1.3;margin:0 0 14px">${m.titulo}</h1>
${m.paragrafos.map(p => `<p style="font-size:15px;line-height:1.6;color:#334155;margin:0 0 12px">${p}</p>`).join('\n')}
${m.botao ? `<p style="margin:26px 0"><a href="${m.botao[1]}" style="background:#4F46E5;color:#ffffff;text-decoration:none;padding:13px 22px;border-radius:10px;font-weight:bold;display:inline-block">${m.botao[0]}</a></p>` : ''}
<p style="font-size:12px;line-height:1.6;color:#94A3B8;margin-top:34px;border-top:1px solid #E2E8F0;padding-top:16px">Nexla Automação e Inteligência Artificial Ltda. · CNPJ 59.838.572/0001-97 · Vilhena – RO<br>Dúvidas: WhatsApp (69) 9930-0101 · nexla@nexla.com.br</p>
</div>`;

const m = MSG[c.evento];
if (!m) return [];
let telefone = String(a.whatsapp || '').replace(/\D/g, '');
if (telefone && !telefone.startsWith('55')) telefone = '55' + telefone;
if (telefone.length < 12) telefone = '';

return [{ json: {
  evento: c.evento,
  pedidoId: c.pedidoId,
  supabaseUrl: c.supabaseUrl,
  evolutionUrl: c.evolutionUrl,
  evolutionInstancia: c.evolutionInstancia,
  evolutionApiKey: c.evolutionApiKey,
  esperaHoras: c.evento === 'boleto_pendente' ? c.esperaBoletoHoras : c.esperaPixHoras,
  telefone,
  email: String(a.email || '').trim(),
  assunto: m.assunto,
  whatsapp: m.whatsapp,
  html: html(m),
  lembrete: m.lembrete ? { assunto: m.lembrete.assunto, whatsapp: m.lembrete.whatsapp, html: html(m.lembrete) } : null,
} }];

// O Pix/boleto continua sem pagar depois da espera: manda o lembrete
const m = $('Montar mensagens').first().json;
if (!m.lembrete) return [];
return [{ json: { ...m, evento: m.evento + '_lembrete', assunto: m.lembrete.assunto, whatsapp: m.lembrete.whatsapp, html: m.lembrete.html } }];
